/**
 * Query classification for the growth report.
 *
 * ## Why this exists
 *
 * Search Console attributes impressions to this site for strings like
 * `d'acord`, `check again`, `si`, `las dos cosas` and `para ir mañana`, at
 * positions 2–6, with no clicks ever. Those are not things a person types into
 * a search box; they are consistent with fan-out sub-queries generated by an
 * AI system. They inflate impressions and crush CTR, and through September
 * they grew fast enough to move the site-wide number on their own.
 *
 * So site-wide CTR mixes two populations with different denominators and is
 * not a usable KPI. This module separates them, so a decision can be made
 * against the queries a human actually typed.
 *
 * ## The rule this file obeys
 *
 * **Nothing is discarded and nothing is bucketed silently.** Every query gets
 * a `kind` and a `reason`, the report prints the reason, and a person can
 * disagree with any single call by reading it. A classifier whose output
 * cannot be audited is worse than no classifier, because it launders a guess
 * into a number.
 *
 * Where a query is genuinely ambiguous — `6 de octubre` could be a fragment or
 * could be somebody asking whether it is a public holiday — it lands in a
 * bucket that says so, rather than being forced into one of the two clean
 * ones.
 *
 * ## Order of checks
 *
 * 1. **Brand.** Our own name, in any spelling.
 * 2. **Topical.** Contains a word from a cluster vocabulary. A topical query
 *    is *always* human, however short: `bolets` is one word and is the most
 *    valuable query on the site.
 * 3. **Noise.** Every token is a confirmation, a deictic, a bare temporal
 *    word or a bare date, and the query is short.
 * 4. **Unclassified.** Everything else. Reported separately and never counted
 *    as qualified, because we do not know what it is.
 */

export type QueryKind = "brand" | "human" | "noise" | "unclassified";

export type ClusterKey =
  | "bolets"
  | "tardor"
  | "gastronomia"
  | "agenda"
  | "sitges"
  | "calendari-laboral"
  | "taxa-turistica"
  | "barcelona-practical"
  | "travel"
  | "destinations";

export interface Classification {
  kind: QueryKind;
  cluster: ClusterKey | null;
  /** Why this call was made, in words, so a person can disagree with it. */
  reason: string;
}

/* -------------------------------------------------------------------------- */
/* Vocabularies                                                               */
/* -------------------------------------------------------------------------- */

/** Lowercase, accents removed, punctuation flattened to spaces. */
export function normalise(query: string): string {
  return query
    .toLowerCase()
    .normalize("NFD")
    .replace(/[̀-ͯ]/g, "")
    .replace(/[^a-z0-9\s]/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

