/* -------------------------------------------------------------------------- */
/* Classification                                                             */
/* -------------------------------------------------------------------------- */

function containsPhrase(text: string, phrase: string): boolean {
  // Word-boundary match on the normalised string, so `mes` does not match
  // inside `mesos` and `si` does not match inside `sitges`.
  const pattern = new RegExp(`(^|\\s)${phrase.replace(/\s+/g, "\\s+")}($|\\s)`);
  return pattern.test(text);
}

/** The cluster a query belongs to, or null when no vocabulary matches. */
export function clusterFor(query: string): ClusterKey | null {
  const text = normalise(query);
  for (const cluster of CLUSTERS) {
    for (const token of cluster.tokens) {
      if (containsPhrase(text, token)) return cluster.key;
    }
  }
  return null;
}

function isBareDate(text: string): boolean {
  const words = text.split(" ").filter(Boolean);
  if (words.length === 0 || words.length > 4) return false;
  return words.every(
    (word) =>
      /^\d{1,4}$/.test(word) ||
      MONTHS.includes(word) ||
      WEEKDAYS.includes(word) ||
      DEICTIC.includes(word),
  );
}

function allIn(text: string, lists: string[][]): boolean {
  const words = text.split(" ").filter(Boolean);
  if (words.length === 0) return false;
  const flat = lists.flat();
  return words.every((word) => flat.includes(word));
}

export function classifyQuery(query: string): Classification {
  const text = normalise(query);

  if (text.length === 0) {
    return { kind: "unclassified", cluster: null, reason: "empty after normalisation" };
  }

  /* 1. Brand ------------------------------------------------------------- */
  for (const brand of BRAND) {
    if (containsPhrase(text, brand) || text.replace(/\s/g, "") === brand.replace(/\s/g, "")) {
      return { kind: "brand", cluster: null, reason: `brand term "${brand}"` };
    }
  }

  /* 2. Topical ----------------------------------------------------------- */
  const cluster = clusterFor(query);
  if (cluster) {
    return { kind: "human", cluster, reason: `topical: matches the ${cluster} vocabulary` };
  }

  /* 3. Noise ------------------------------------------------------------- */
  const words = text.split(" ").filter(Boolean);

  // Multi-word fixed fragments first, so "las dos cosas" is caught as a phrase.
  for (const phrase of [...CONFIRMATION, ...TEMPORAL, ...DEICTIC].filter((p) => p.includes(" "))) {
    if (text === phrase) {
      return { kind: "noise", cluster: null, reason: `fixed fragment "${phrase}"` };
    }
  }

  if (words.length <= 4 && allIn(text, [CONFIRMATION, TEMPORAL, DEICTIC])) {
    return {
      kind: "noise",
      cluster: null,
      reason: "every word is a confirmation, a deictic or a bare temporal word",
    };
  }

  if (isBareDate(text)) {
    // Ambiguous on purpose: this could be someone asking whether a date is a
    // public holiday. Counted as noise, but the reason says why, and the
    // report prints it so the call can be overruled.
    return { kind: "noise", cluster: null, reason: "bare date with no subject" };
  }

  if (words.length === 1 && words[0] && words[0].length <= 3) {
    return { kind: "noise", cluster: null, reason: "single token of three characters or fewer" };
  }

  /* 4. Unknown ----------------------------------------------------------- */
  return {
    kind: "unclassified",
    cluster: null,
    reason: "no brand, no cluster vocabulary, not a recognised fragment",
  };
}

/* -------------------------------------------------------------------------- */
/* Opportunity score                                                          */
/* -------------------------------------------------------------------------- */

export interface QueryRow {
  query: string;
  clicks: number;
  impressions: number;
  ctr: number;
  position: number;
}

export interface Opportunity {
  score: number;
  /** Every term that went into the score, so the number can be argued with. */
  terms: string[];
}

/**
 * How much a query is worth going after, on a scale nobody should treat as
 * precise.
 *
 * Deliberately a handful of additions rather than a model: the inputs are
 * three numbers and a label, and anything more elaborate would imply a
 * confidence the data does not support. No search-volume estimate is invented;
 * impressions are the only volume signal used, because they are the only one
 * measured.
 */
export function opportunityScore(row: QueryRow, classification: Classification): Opportunity {
  const terms: string[] = [];
  let score = 0;

  if (classification.kind !== "human") {
    return {
      score: 0,
      terms: [`not a human query (${classification.kind}) — no opportunity claimed`],
    };
  }

  score += 3;
  terms.push("+3 human query with clear intent");

  const volume = Math.min(row.impressions / 10, 4);
  score += volume;
  terms.push(`+${volume.toFixed(1)} volume (${row.impressions} impressions, capped at 4)`);

  if (row.position >= 5 && row.position <= 20) {
    score += 3;
    terms.push(`+3 position ${row.position.toFixed(1)}: close enough to move`);
  } else if (row.position > 20 && row.position <= 40) {
    score += 1.5;
    terms.push(`+1.5 position ${row.position.toFixed(1)}: reachable with a dedicated page`);
  } else if (row.position > 40) {
    score += 0.5;
    terms.push(`+0.5 position ${row.position.toFixed(1)}: only worth it with new content`);
  } else if (row.position <= 3) {
    score -= 4;
    terms.push(`-4 position ${row.position.toFixed(1)}: already won, nothing to gain`);
  } else {
    terms.push(`+0 position ${row.position.toFixed(1)}`);
  }

  // A query with words beyond its cluster term is asking something specific
  // that a general page answers badly. That is where a new page can win
  // without competing with the one we already rank with.
  const words = normalise(row.query).split(" ").filter(Boolean);
  if (words.length >= 3) {
    score += 2;
    terms.push("+2 specific phrasing: a general page answers it poorly");
  }

  if (row.clicks === 0 && row.impressions >= 10) {
    score += 1;
    terms.push("+1 impressions but no clicks: visible and not chosen");
  }

  return { score: Math.round(score * 10) / 10, terms };
}
